"""Generate PyInstaller version_info.txt from src.config.APP_VERSION."""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from src.config import APP_VERSION  # noqa: E402

parts = [int(p) for p in APP_VERSION.split(".")[:3]]
while len(parts) < 3:
    parts.append(0)
filevers = (parts[0], parts[1], parts[2], 0)
ver_str = APP_VERSION

out = ROOT / "version_info.txt"
content = f"""# UTF-8
# Auto-generated by tools/gen_version_info.py - do not edit by hand.
VSVersionInfo(
  ffi=FixedFileInfo(
    filevers={filevers!r},
    prodvers={filevers!r},
    mask=0x3f,
    flags=0x0,
    OS=0x40004,
    fileType=0x1,
    subtype=0x0,
    date=(0, 0)
  ),
  kids=[
    StringFileInfo(
      [
      StringTable(
        u'040904B0',
        [StringStruct(u'CompanyName', u'Civ4 PBEM Manager contributors'),
        StringStruct(u'FileDescription', u'Civilization 4 Play-By-Email Manager'),
        StringStruct(u'FileVersion', u'{ver_str}'),
        StringStruct(u'InternalName', u'Civ4PBEMManager'),
        StringStruct(u'LegalCopyright', u'Copyright (c) 2026 zfkibuj-hash and contributors (MIT)'),
        StringStruct(u'OriginalFilename', u'Civ4PBEMManager.exe'),
        StringStruct(u'ProductName', u'Civ4 PBEM Manager'),
        StringStruct(u'ProductVersion', u'{ver_str}')])
      ]),
    VarFileInfo([VarStruct(u'Translation', [1033, 1200])])
  ]
)
"""
out.write_text(content, encoding="utf-8")
print(f"Wrote {out} for version {ver_str}")
